const urls = ["https://opencode.ai/pricing", "https://opencode.ai/docs/zen/", "https://opencode.ai/go"];
const out = [];
for (const u of urls) {
  try {
    const res = await fetch(u, { headers: { "user-agent": "Mozilla/5.0" } });
    const text = await res.text();
    out.push({ u, status: res.status, len: text.length, head: text.slice(0, 1200) });
  } catch (e) {
    out.push({ u, error: String(e) });
  }
}
return out;

