  return { status:r.status, text: h.replace(/<script[\s\S]*?<\/script>/gi," ").replace(/<style[\s\S]*?<\/style>/gi," ").replace(/<[^>]+>/g,"\n").replace(/&nbsp;/g," ").replace(/&amp;/g,"&").replace(/&quot;/g,'"').replace(/&#x27;|&#39;/g,"'").replace(/&lt;/g,"<").replace(/&gt;/g,">").split("\n").map(s=>s.trim()).filter(Boolean).join("\n") };
}
const go = await grab("https://opencode.ai/v2/docs/console/go/");
const ws = await grab("https://opencode.ai/v2/docs/console/workspaces/");
const pick = (t) => { const i = t.toLowerCase().indexOf("privacy"); return i < 0 ? "NO PRIVACY SECTION" : t.slice(Math.max(0,i-800), i+2500); };
return { go: pick(go.text), ws: pick(ws.text) };

